CREATE OR REPLACE FUNCTION public.guard_digital_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE key_id uuid; BEGIN IF TG_OP='INSERT' THEN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.payment_method||':'||upper(NEW.trx_id),0)); IF EXISTS(SELECT 1 FROM public.digital_orders WHERE payment_method=NEW.payment_method AND upper(trx_id)=upper(NEW.trx_id)) OR EXISTS(SELECT 1 FROM public.orders WHERE payment_method=NEW.payment_method AND upper(transaction_id)=upper(NEW.trx_id)) OR EXISTS(SELECT 1 FROM public.gear_orders WHERE payment_method=NEW.payment_method AND upper(trx_id)=upper(NEW.trx_id)) THEN RAISE EXCEPTION 'Payment transaction already used'; END IF; NEW.trx_id=upper(NEW.trx_id); ELSE IF OLD.status IN ('delivered','cancelled') AND NEW.status<>OLD.status THEN RAISE EXCEPTION 'Terminal order cannot change status'; END IF; IF NEW.status='cancelled' AND (OLD.status<>'pending' OR OLD.delivery_status<>'none') THEN RAISE EXCEPTION 'Only unfulfilled pending orders may be cancelled'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_digital_order BEFORE INSERT OR UPDATE OF status ON public.digital_orders FOR EACH ROW EXECUTE FUNCTION public.guard_digital_order();
CREATE OR REPLACE FUNCTION public.reserve_digital_order_key() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE key_id uuid; BEGIN IF TG_OP='INSERT' AND NEW.product_slug='chatgpt-plus-renew' THEN SELECT id INTO key_id FROM public.digital_key_inventory WHERE product_slug=NEW.product_slug AND order_id IS NULL ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT 1; IF key_id IS NULL THEN RAISE EXCEPTION 'Key inventory unavailable'; END IF; UPDATE public.digital_key_inventory SET order_id=NEW.id WHERE id=key_id; ELSIF TG_OP='UPDATE' AND NEW.status='cancelled' AND OLD.status='pending' THEN UPDATE public.digital_key_inventory SET order_id=NULL WHERE order_id=NEW.id AND assigned_at IS NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER reserve_digital_order_key AFTER INSERT OR UPDATE OF status ON public.digital_orders FOR EACH ROW EXECUTE FUNCTION public.reserve_digital_order_key();